import pyomo.environ as pyo

DATA = {
    "foods": [
        "Chicken", "Tofu", "BrownRice", "Fish", "Lentils",
        "Quinoa", "Eggs", "Beef", "Beans",
    ],
    "cost": {
        "Chicken": 10, "Tofu": 2, "BrownRice": 7, "Fish": 8, "Lentils": 4,
        "Quinoa": 9, "Eggs": 2, "Beef": 9, "Beans": 9,
    },
    "protein": {
        "Chicken": 7, "Tofu": 12, "BrownRice": 14, "Fish": 9, "Lentils": 11,
        "Quinoa": 10, "Eggs": 10, "Beef": 9, "Beans": 8,
    },
    "carb": {
        "Chicken": 17, "Tofu": 12, "BrownRice": 27, "Fish": 6, "Lentils": 19,
        "Quinoa": 23, "Eggs": 6, "Beef": 16, "Beans": 25,
    },
    "cal": {
        "Chicken": 95, "Tofu": 233, "BrownRice": 134, "Fish": 109, "Lentils": 202,
        "Quinoa": 148, "Eggs": 184, "Beef": 136, "Beans": 229,
    },
    "protein_min": 71,
    "carb_min": 107,
    "cal_min": 1623,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Decision variable: x[f] = servings (units) of food f
    # f in FOODS, domain NonNegativeReals, bounds (0, None)
    F = d["foods"]
    model.F = pyo.Set(initialize=F, ordered=True)

    model.x = pyo.Var(model.F, domain=pyo.NonNegativeReals, bounds=(0, None))

    # Objective (minimize) : total cost
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in F)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient >= requirement (one per nutrient)
    def protein_rule(m):
        return sum(d["protein"][f] * m.x[f] for f in F) >= d["protein_min"]
    model.protein_constraint = pyo.Constraint(rule=protein_rule)

    def carb_rule(m):
        return sum(d["carb"][f] * m.x[f] for f in F) >= d["carb_min"]
    model.carb_constraint = pyo.Constraint(rule=carb_rule)

    def cal_rule(m):
        return sum(d["cal"][f] * m.x[f] for f in F) >= d["cal_min"]
    model.cal_constraint = pyo.Constraint(rule=cal_rule)

    return model


if __name__ == "__main__":
    model = build_model()
    model.pprint()

import pyomo.environ as pyo

DATA = {
    "foods": [
        "Chicken", "Tofu", "BrownRice", "Fish", "Lentils",
        "Quinoa", "Eggs", "Beef", "Beans",
    ],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per unit of each food
    "cost": {
        "Chicken": 10, "Tofu": 2, "BrownRice": 7, "Fish": 8, "Lentils": 4,
        "Quinoa": 9, "Eggs": 2, "Beef": 9, "Beans": 9,
    },
    # nutrient content per unit of each food
    "content": {
