            "Quinoa": 10, "Eggs": 10, "Beef": 9, "Beans": 8,
        },
        "carbs": {
            "Chicken": 17, "Tofu": 12, "BrownRice": 27, "Fish": 6, "Lentils": 19,
            "Quinoa": 23, "Eggs": 6, "Beef": 16, "Beans": 25,
        },
        "calories": {
            "Chicken": 95, "Tofu": 233, "BrownRice": 134, "Fish": 109, "Lentils": 202,
            "Quinoa": 148, "Eggs": 184, "Beef": 136, "Beans": 229,
        },
    },
    # minimum daily requirements
    "requirement": {"protein": 71, "carbs": 107, "calories": 1623},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # servings[f] >= 0 : how many units of food f to buy
    model.servings = pyo.Var(
        model.FOODS, within=pyo.NonNegativeReals, bounds=(0, None)
    )

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient requirements: at least the daily minimum for each nutrient
    def nutrient_rule(m, n):
        return sum(
            d["content"][n][f] * m.servings[f] for f in m.FOODS
        ) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


