def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Sets
    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # Decision variables: amount of each food (continuous, nonnegative)
    model.x = pyo.Var(model.I, within=pyo.NonNegativeReals)

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: meet each nutrient requirement (at least)
    def nutrient_rule(m, n):
        key = d["content_key"][n]
        return sum(d[key][i] * m.x[i] for i in m.I) >= d["requirement"][n]
    model.nutrient_constraint = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
